// ===========================================================================
// splash_core.h -- the CYDpod startup screen, independent of the display driver
// ===========================================================================
// Yellow screen, wordmark centred a little above the middle. The wordmark is a 4-bit alpha mask
// (splash_logo.h, generated by tools/gen_splash.py) blended between ink and yellow one row at a
// time through a Sink, so there is no frame buffer. A Sink provides:
//   void fill(uint16_t colour);                                  whole screen
//   void row(int x, int y, int n, uint16_t* px);                 n native RGB565 pixels; may modify px
// splash.cpp binds it to TFT_eSPI; tests/splash_test.cpp binds it to a fake framebuffer.
#pragma once

#include <stdint.h>
#include "splash_logo.h"

#ifndef pgm_read_byte
#define pgm_read_byte(p) (*(const uint8_t*)(p))
#endif

namespace splash {

constexpr uint8_t YELLOW_R = 0xFF, YELLOW_G = 0xD2, YELLOW_B = 0x1F;   // #FFD21F
constexpr uint8_t INK_R = 0x1D, INK_G = 0x1D, INK_B = 0x1F;            // #1D1D1F

constexpr uint16_t rgb565(uint8_t r, uint8_t g, uint8_t b) {
  return (uint16_t)(((r & 0xF8) << 8) | ((g & 0xFC) << 3) | (b >> 3));
}
constexpr uint16_t BACKGROUND = rgb565(YELLOW_R, YELLOW_G, YELLOW_B);  // 0xFE83
constexpr uint16_t INK = rgb565(INK_R, INK_G, INK_B);                  // 0x18E3

struct Layout {
  int x, y, w, h;          // where the mask goes
  const uint8_t* mask;
};

// Landscape when the panel is wider than tall (rotation 1 and 3); portrait otherwise. The wordmark's
// vertical centre sits at 45% of the height, i.e. 5% of the height above the middle.
inline Layout layout(int sw, int sh) {
  const bool land = sw > sh;
  Layout l;
  l.w = land ? SPLASH_LANDSCAPE_W : SPLASH_PORTRAIT_W;
  l.h = land ? SPLASH_LANDSCAPE_H : SPLASH_PORTRAIT_H;
  l.mask = land ? SPLASH_LANDSCAPE : SPLASH_PORTRAIT;
  l.x = (sw - l.w) / 2;
  l.y = sh * 45 / 100 - l.h / 2;
  return l;
}

inline int centreY(int sh) { return sh * 45 / 100; }

constexpr int MAX_ROW = SPLASH_LANDSCAPE_W > SPLASH_PORTRAIT_W ? SPLASH_LANDSCAPE_W : SPLASH_PORTRAIT_W;

template <class Sink>
void render(Sink& s, int sw, int sh) {
  s.fill(BACKGROUND);
  const Layout l = layout(sw, sh);
  uint16_t lut[16];                        // 32 B
  for (int a = 0; a < 16; a++) {
    lut[a] = rgb565((uint8_t)((INK_R * a + YELLOW_R * (15 - a) + 7) / 15),
                    (uint8_t)((INK_G * a + YELLOW_G * (15 - a) + 7) / 15),
                    (uint8_t)((INK_B * a + YELLOW_B * (15 - a) + 7) / 15));
  }
  uint16_t line[MAX_ROW];                  // at most 512 B
  const int stride = (l.w + 1) / 2;
  for (int y = 0; y < l.h; y++) {
    const uint8_t* src = l.mask + y * stride;
    for (int x = 0; x < l.w; x++) {
      const uint8_t b = pgm_read_byte(src + (x >> 1));
      line[x] = lut[(x & 1) ? (b & 15) : (b >> 4)];
    }
    s.row(l.x, l.y + y, l.w, line);
  }
}

}  // namespace splash
